import React from "react";
import { BrowserRouter, Routes, Route, Navigate } from "react-router-dom";

import ProtectedRoute from "./components/Protected/ProtectedRoute";
import RequireAdmin from "./components/Protected/RequireAdmin";

import Login from "./components/Login/Login"; // hoặc đúng path Login bạn đang dùng
import AdminLayout from "./components/Admin/AdminLayout";
import Usermanagement from "./components/Admin/UserManagement"; // bạn đang có

function Forbidden() {
  return <div style={{ padding: 20 }}>403 - Forbidden</div>;
}

function AdminDashboard() {
  return <div>Admin Dashboard</div>;
}

export default function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/login" element={<Login />} />
        <Route path="/forbidden" element={<Forbidden />} />

        {/* Chặn mọi route cần đăng nhập */}
        <Route element={<ProtectedRoute />}>
          {/* Admin layout */}
          <Route path="/admin" element={<AdminLayout />}>
            <Route index element={<AdminDashboard />} />

            {/* Chỉ ADMIN mới vào user management */}
            <Route element={<RequireAdmin />}>
              <Route path="users" element={<Usermanagement />} />
            </Route>
          </Route>
        </Route>

        <Route path="/" element={<Navigate to="/login" replace />} />
        <Route path="*" element={<Navigate to="/login" replace />} />
      </Routes>
    </BrowserRouter>
  );
}
